function eb.charmScore(ln,mn)
local nn=(mn and tonumber(mn.p))or 0.5
local pn,qn,rn=ln.rolls.unit_damage or 0,ln.rolls.reward_mul or 0,0
for sn,tn in pairs(ln.rolls)do
if sn~=pxc[1697]and sn~=pxc[1698]then
rn=rn+tn
end
end
if nn>=0.92 then
return qn*3+pn+rn*0.5
end
return pn*3+qn+rn*0.5
end
