function eb.charmDmg(yn)
if type(yn)~=pxc[1482]or not(eb.is(yn.id)or yn.portal_group==pxc[1703]or tostring(yn.id):find(pxc[1704],1,true))then
return 0
end
local zn,An=eb.charmOn(),0
for Bn,Cn in ipairs(eb.charms())do
local Dn=Cn.rolls.unit_damage or 0
if zn and Cn.uuid==zn then
return Dn
end
if I.smartCharm and Dn>An then
An=Dn
end
end
return zn and 0 or An
