function eb.charmWant(En)
if not I.smartCharm or not eb.charmApplies(En)then
return nil
end
J.charm=type(J.charm)==pxc[1482]and J.charm or{}
if os.time()-(tonumber(J.charm.failAt)or 0)<1800 then
return nil
end
local Fn,Gn
for Hn,In in ipairs(eb.charms())do
local Jn=eb.charmScore(In,En)
if not Gn or Jn>Gn then
Fn,Gn=In,Jn
end
end
if not Fn then
return nil
end
local Kn=eb.charmOn()or(j.where==pxc[1550]and J.charm.uuid)or nil
if Kn==Fn.uuid then
return nil
end
return Fn,Kn
