function eb.charmTick(Ln)
local Mn,Nn=eb.charmWant(Ln)
if not Mn then
return
end
Nn=eb.charmOn()
if Nn then
j.request(pxc[1705],pxc[1706],Nn)
task.wait(1)
end
j.request(pxc[1705],pxc[1707],Mn.uuid)
local On=M.now()
while M.now()-On<4 and eb.charmOn()~=Mn.uuid do
task.wait(0.5)
end
if eb.charmOn()==Mn.uuid then
J.charm.uuid,J.charm.at,J.charm.failAt=Mn.uuid,os.time(),nil
j.saveSoon()
j.log(1,pxc[1708],string.format(pxc[1709],eb.charmWords(Mn),tostring(Ln.label),math.floor((tonumber(Ln.p)or 0)*100+0.5),(tonumber(Ln.p)or 0)>=0.92 and pxc[1700]or pxc[1616]))
else
J.charm.failAt=os.time()
j.saveSoon()
j.log(1,pxc[1708],string.format(pxc[1710],eb.charmWords(Mn)))
end
end
function eb.weatherStrength(Pn)
local Qn=eb.fx(Pn)
local Rn=Qn.dmg/Qn.cd/Qn.hp/Qn.speed*(1+(Qn.range-1)/2)
for Sn,Tn in pairs(Qn.kinds)do
Rn=Rn*(1+Q.rogueShare(Sn)*Tn)
end
if Qn.ice>0 then
local Un=Q.rogueShare(pxc[1661])
Rn=Rn*(Un+(1-Un)/(1-Qn.ice+Qn.ice/W.modFactor(pxc[1711])))
end
if Qn.fly>0 then
Rn=Rn*(1-Qn.fly*0.5)
end
if Qn.noCC then
Rn=Rn*0.95
end
if Qn.shroud then
Rn=Rn*0.9
end
return Rn
end
function eb.cardGems(Vn,Wn)
local Xn=0
local Yn=eb.pearlsFrom(Wn+1,50)
for Zn,ao in pairs(type(Vn.effects)==pxc[1482]and Vn.effects or{})do
if type(ao)==pxc[1482]then
local bo=tonumber(ao.amount)or 0
if ao.type==pxc[1712]then
Xn=Xn+math.abs(bo)*Yn*I.pearlValue
elseif ao.type==pxc[1713]then
local co,eo=pcall(O.rewardValue,ao.reward)
if co then
Xn=Xn+(tonumber(eo)or 0)
end
elseif ao.type==pxc[1714]then
Xn=Xn+bo*eb.STARFALL_GEMS
elseif ao.type==pxc[1715]then
Xn=Xn+bo*100
end
end
end
if Vn.option_type==pxc[1716]then
Xn=Xn+eb.HARD_GEMS
end
if Vn.weather then
local fo=Vn.weather~=eb.weatherNow()
if fo and Vn.weather==pxc[1664]then
Xn=Xn+eb.STARFALL_GEMS
end
local go=eb.board()
if fo and go and Vn.weather~=pxc[1670]and not go.weathers[Vn.weather]then
Xn=Xn+(1000+5000*I.pearlValue+50*(H.ITEM_VALUE.star_remnant_limited or 25))/eb.WEATHERS
end
end
return Xn
end
