return
end
local Pp=H.session()
local function Qp(Rp,Sp,Tp)
local Up=j.gameSaid(Sp)
P.pickNote.skins=string.format(pxc[1763],Rp,tostring(Up or Tp or pxc[1764]))
j.log(1,pxc[1683],P.pickNote.skins)
j.backoff(pxc[1765],1800)
end
local Vp=eb.skinPlan()
if I.skinSmart then
local Wp=Vp.wear[1]
if Wp and(j.req.back.skinWear or 0)<=M.now()then
local Xp=db.slotOf(Wp.unit)
if Xp then
J.str.reequip={uuid=Wp.unit,slot=Xp}
j.saveNow()
j.request(pxc[1766],pxc[1767],Wp.unit)
local Yp=M.now()
while M.now()-Yp<4 and db.slotOf(Wp.unit)do
