end
end
local Zp=M.now()
local _p,aq=j.request(pxc[1768],pxc[1707],Wp.uuid,{unit_uuid=Wp.unit})
local function bq()
local cq=Pp.collection:get_unit_by_uuid(Wp.unit)
return cq and cq.skin~=nil
end
while M.now()-Zp<5 and not bq()do
task.wait(0.25)
end
if Xp then
db.reequip()
end
if bq()then
j.log(1,pxc[1683],string.format(pxc[1769],Wp.name,Wp.unitName))
P.pickNote.skins=nil
Vp=eb.skinPlan()
else
local dq=j.gameSaid(Zp)
P.pickNote.skins=string.format(pxc[1770],Wp.name,tostring(dq or aq or pxc[1764]))
j.log(1,pxc[1683],P.pickNote.skins)
j.backoff(pxc[1768],1800)
end
end
if#Vp.sell>0 then
local eq,fq={},0
for gq=1,math.min(50,#Vp.sell)do
