fq=fq+Vp.sell[gq].pearls
end
local hq=tonumber(H.cur(pxc[1737]))or 0
local iq=M.now()
local jq,kq=j.request(pxc[1771],pxc[1772],eq)
while M.now()-iq<5 and(tonumber(H.cur(pxc[1737]))or 0)<=hq do
task.wait(0.25)
end
local lq=(tonumber(H.cur(pxc[1737]))or 0)-hq
if lq<=0 then
