return oq and tonumber(pq)or 0
end
local qq=M.now()
for rq=1,8 do
if M.now()-qq>15 or not j.alive or j.where~=pxc[1549]then
break
end
local sq=nq()
local tq=eb.starPlan(eb.skinPlan())
local uq=M.now()
if sq>0 then
local vq,wq=j.request(pxc[1776],pxc[1777],eb.STAR,{use10=sq>=10,use_all=false})
while M.now()-uq<6 and nq()>=sq do
task.wait(0.25)
end
if nq()>=sq then
return Qp(pxc[1778],uq,wq)
end
j.log(1,pxc[1683],string.format(pxc[1779],sq-nq(),(tonumber(((H.prof().capsule_pity_data or{})[eb.STAR]or{}).total_opens)or 0)))
P.pickNote.skins=nil
elseif tq.open>0 then
local xq=tq.open>=10 and 10 or 1
local yq=tonumber(H.cur(pxc[1737]))or 0
local zq,Aq=j.request(pxc[1780],pxc[1781],eb.STAR,pxc[1499],pxc[1782],tostring(xq))
while M.now()-uq<5 and nq()<=0 do
task.wait(0.25)
end
if nq()<=0 then
return Qp(pxc[1783],uq,Aq)
end
R.add(string.format(pxc[1784],nq()),yq-(tonumber(H.cur(pxc[1737]))or 0),pxc[1785],pxc[1786]..tq.why)
P.pickNote.skins=nil
else
