function db.gainXp(gK,hK)
local iK,jK=tonumber(gK.xp)or 0,db.xpFor(gK.unit_id,db.cap(gK))
local kK=math.max(0,jK-iK)
if kK<=0 or(hK or 0)<=0 then
return 0,0
end
local lK=math.min(hK,kK)
local mK=db.base(gK)
if mK<=0 then
return 0,lK
end
return db.share(gK.unit_id)*(db.score(db.whatIf(gK,{xp=iK+lK}))/mK-1)*100,lK
end
function db.gainFuse(nK)
if db.lb(nK)>=1 then
return 0
end
local oK=db.base(nK)
if oK<=0 then
return 0
end
local pK=db.whatIf(nK,{xp=math.max(tonumber(nK.xp)or 0,db.xpFor(nK.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return db.share(nK.unit_id)*(db.score(pK)/oK-1)*100+5
end
