function db.relicWorth(qK,rK)
local sK=rK._unique_item_data and rK._unique_item_data._unique_relic_data
if not sK then
return 0
end
local tK=H.Items[rK.item_id]or{}
local uK,vK=N.types(qK.unit_id)
if tK.main_damage_type and tK.main_damage_type~=pxc[2100]and tK.main_damage_type~=vK then
return 0
end
local wK,xK=0,0
for yK,zK in pairs(sK._core_damage_type_buffs or{})do
if uK[zK.damage_type]then
wK=wK+(tonumber(zK.mul)or 0)+(tonumber(zK.add_upg)or 0)*0.01+(tonumber(zK.pen)or 0)*0.001
xK=xK+(tonumber(zK.crit)or 0)
end
end
wK=wK+xK*0.5
local AK=N.rows(qK.unit_id)
local BK=AK and AK[AK.max]
local CK=(BK and tonumber(BK.cd)or 0)*N.mult(qK,pxc[1617])
for DK,EK in pairs(sK._unique_relic_effects or{})do
local FK=type(EK.params)==pxc[1482]and EK.params or{}
if EK.id==pxc[2101]then
local GK=math.min(1,(tonumber(FK.extra_damage)or 0)*CK/math.max(1,tonumber(FK.time_interval)or 40))
local HK=N.DRONES and N.DRONES[qK.unit_id]
if HK and HK.late and CK>0 then
local IK=1/CK
GK=GK*IK/(IK+(tonumber(HK.max)or 0)*(tonumber(HK.late.dmg)or 0)*(tonumber(HK.hits)or 1)/math.max(0.1,tonumber(HK.late.cd)or 4))
end
wK=wK+GK
elseif EK.id==pxc[2102]then
wK=wK+(tonumber(FK.dmg_buff)or 0)*0.25
elseif EK.id==pxc[2103]then
wK=wK+(tonumber(FK.dmg_buff)or 0)*xK
elseif EK.id==pxc[2104]then
if uK.magic then
wK=0
else
wK=wK+(tonumber(FK.dmg_buff)or 0)*0.3
end
elseif EK.id==pxc[2105]then
if uK.water_damage then
wK=wK+0.05
end
end
end
return wK
end
function db.relicPlan()
local JK=H.session()
