if WK>0.01 then
table.insert(TK,{it=VK,w=WK})
end
end
table.sort(TK,function(XK,YK)
if XK.w~=YK.w then
return XK.w>YK.w
end
return XK.it.uuid<YK.it.uuid
end)
local ZK,_K={},{}
for aL,bL in ipairs(TK)do
local cL=_K[bL.it.item_id]or 0
if#ZK<6 and cL<((H.Items[bL.it.item_id]or{}).unique_equip and 1 or 2)then
_K[bL.it.item_id]=cL+1
table.insert(ZK,bL)
end
end
if QK.u._equipped_relic then
local dL=false
