if not kL[rL.it.uuid]and not(sL and lL[rL.it.item_id])then
kL[rL.it.uuid]=true
if sL then
lL[rL.it.item_id]=true
end
jL[pL.e.uuid]=rL.it.uuid
mL(nL+1,oL+rL.w+(rL.it.uuid==pL.e.u._equipped_relic and 0.01 or 0))
jL[pL.e.uuid]=nil
kL[rL.it.uuid]=nil
if sL then
lL[rL.it.item_id]=nil
end
end
end
end
mL(1,0)
local tL,uL=0,{}
for vL,wL in ipairs(OK)do
local xL=wL.e.u._equipped_relic and JK.inventory:get_item_by_uuid(wL.e.u._equipped_relic)
local yL=xL and db.relicWorth(wL.e.u,xL)*wL.share*100 or 0
tL=tL+yL
local zL=hL[wL.e.uuid]and JK.inventory:get_item_by_uuid(hL[wL.e.uuid])
local AL=zL and db.relicWorth(wL.e.u,zL)*wL.share*100 or 0
table.insert(uL,string.format(pxc[2108],N.name(wL.e.id),xL and(H.Items[xL.item_id]or{}).name or pxc[1751],yL,zL and(H.Items[zL.item_id]or{}).name or pxc[1751],AL))
end
return hL,iL-tL,uL,OK
end
