function P.fuseFuel(qQ,rQ)
local sQ=H.session()
local tQ={[qQ.uuid]=true,[I.evolveUnit]=true,[I.fuseXpUnit]=true}
local uQ={}
for vQ,wQ in ipairs(N.equipped())do
tQ[wQ.uuid]=true
end
for xQ,yQ in ipairs(J.savedTeam or{})do
tQ[yQ]=true
end
for zQ,AQ in ipairs(J.train and J.train.on and J.train.on.base or{})do
tQ[AQ]=true
end
for BQ,CQ in ipairs(J.goals or{})do
tQ[CQ.uuid]=true
for DQ,EQ in ipairs(CQ.eats or{})do
uQ[EQ.id]=true
end
end
for FQ,GQ in ipairs(J.str and J.str.core or{})do
tQ[GQ]=true
end
local HQ=ab.strongest(10)
local IQ,JQ={},0
for KQ,LQ in pairs(sQ.profile_data.collection.owned_units)do
local MQ=sQ.collection:get_unit_by_uuid(KQ)or LQ
local NQ,OQ,PQ=pcall(H.USC.is_unit_good_for_fusion,qQ,MQ)
if NQ and OQ and not(LQ._locked or MQ._locked)and not tQ[KQ]and not uQ[MQ.unit_id]and not(LQ._equipped_relic or MQ._equipped_relic)and not(LQ.shiny or MQ.shiny)and not N.trait(MQ)and not(LQ.further_modifiers and LQ.further_modifiers.limit_break)then
local QQ=ab.fodderOrder(MQ.unit_id)
if QQ and not HQ[KQ]then
local RQ,SQ=pcall(N.score,MQ)
table.insert(IQ,{uuid=KQ,id=MQ.unit_id,pts=tonumber(PQ)or 1,sc=RQ and SQ or 0,order=QQ})
JQ=JQ+(tonumber(PQ)or 1)
end
end
end
table.sort(IQ,function(TQ,UQ)
if TQ.order~=UQ.order then
return TQ.order<UQ.order
end
if TQ.sc~=UQ.sc then
return TQ.sc<UQ.sc
end
return TQ.uuid<UQ.uuid
end)
local VQ,WQ={},0
for XQ,YQ in ipairs(IQ)do
if WQ>=rQ then
break
end
table.insert(VQ,YQ)
WQ=WQ+YQ.pts
end
return VQ,WQ,JQ
end
function P.fodderRows(ZQ)
