end
if#jT==0 then
P.pickNote.autoFuseXp=pxc[2232]
return
end
if os.time()-(tonumber(I.fuseXpOnAt)or 0)<30 then
P.pickNote.autoFuseXp=pxc[2233]
return
end
P.pickNote.autoFuseXp=nil
if j.req.back.fuseXp and M.now()<j.req.back.fuseXp then
return
end
P.fuseBatch=P.fuseBatch or 50
local mT,nT,oT=0,0,{}
while j.alive and mT<10 do
if mT>0 then
local pT,qT,rT=P.xpFodder(gT.collection:get_unit_by_uuid(I.fuseXpUnit)or hT)
