table.insert(jT,tT)
end
end
if lT<=0 or#jT==0 then
break
end
end
local uT={}
for vT=1,math.min(P.fuseBatch,#jT)do
table.insert(uT,jT[vT].uuid)
end
local wT=tonumber((gT.collection:get_unit_by_uuid(I.fuseXpUnit)or hT).xp)or 0
local xT=M.now()
local yT,zT=j.request(pxc[2234],pxc[2235],I.fuseXpUnit,uT)
if not yT and(zT==pxc[1552]or zT==pxc[1551])then
