end
nT=nT+1
task.wait(3.5)
continue
end
while M.now()-xT<5 and(tonumber((gT.collection:get_unit_by_uuid(I.fuseXpUnit)or hT).xp)or 0)<=wT do
task.wait(0.1)
end
local AT=tonumber((gT.collection:get_unit_by_uuid(I.fuseXpUnit)or hT).xp)or 0
if AT>wT then
mT=mT+1
for BT,CT in ipairs(uT)do
oT[CT]=true
end
