j.log(1,pxc[1683],string.format(pxc[2239],#uT,iT,M.fmt(AT-wT),db.level(gT.collection:get_unit_by_uuid(I.fuseXpUnit)or hT)))
elseif#uT>20 then
P.fuseBatch=20
j.log(1,pxc[1683],string.format(pxc[2240],#uT,tostring(j.gameSaid(xT)or(yT and zT)or pxc[1764])))
else
local ET=j.gameSaid(xT)
P.pickNote.autoFuseXp=pxc[2241]..tostring(ET or(yT and zT)or pxc[1764])..pxc[2242]
j.log(1,pxc[1683],pxc[2243]..tostring(ET or(yT and zT)or pxc[1764]))
j.backoff(pxc[2234],1800)
