W.INF_CAP=80
function W.evaluate(Hob,Iob)
local Job=W.run(Hob,Iob,{hpMul=1})
local Kob={won=Job.won,wave=Job.wave,minutes=Job.t/60,aliveAt=Job.aliveAt,total=Hob.total,at=os.time()}
if Hob.infinite and W.unbound(Hob.ld)then
Kob.p=1
Kob.margin=Job.won and string.format(pxc[2703],Hob.total)or string.format(pxc[2704],Job.wave,Job.t/60)
elseif Job.won then
local Lob=W.run(Hob,Iob,{hpMul=1.3})
Kob.p=Lob.won and 0.92 or 0.7
Kob.margin=Lob.won and pxc[2705]or pxc[2706]
else
local Mob=W.run(Hob,Iob,{hpMul=0.75})
Kob.p=Mob.won and 0.25 or 0.05
Kob.margin=Mob.won and string.format(pxc[2707],Job.wave)or string.format(pxc[2708],Job.wave,Hob.total)
if not Mob.won then
local Nob=W.run(Hob,Iob,{hpMul=0.25})
if not Nob.won then
Kob.p,Kob.hopeless=0.005,true
Kob.margin=string.format(pxc[2709],Job.wave,Hob.total)
end
end
end
return Kob
end
function W.trust(Oob,Pob)
