local Rob={}
for Sob,Tob in ipairs(Pob)do
table.insert(Rob,Tob.u)
end
return Rob
end)())then
return nil
end
if Oob.key==pxc[1793]and not Qob.aliveLvl then
return nil
end
if Qob.aliveLvl and Oob.ld and Oob.ld.id and Qob.aliveLvl~=tostring(Oob.ld.id)..(eb.is(Oob.ld.id)and(pxc[2710]..tostring(Oob.ld.map))or pxc[411])then
return nil
