local apb=Vob/Wob
return{ratio=apb,ok=apb>=0.75 and apb<=1.33,waves=Xob}
end
W.GROWN_LEVEL,W.GROWN_MIN=50,6
function W.grownKinds()
local bpb=H.session()
local cpb,dpb={},0
for epb,fpb in pairs(bpb.profile_data.collection.owned_units)do
local gpb=fpb.unit_id
if not cpb[gpb]and H.Units[gpb]and not N.isFarm(gpb)and N.rows(gpb)and not N.hidden(gpb)then
local hpb,ipb=pcall(H.USC.calculate_level,gpb,tonumber(fpb.xp)or 0)
if hpb and(tonumber(ipb)or 0)>=W.GROWN_LEVEL then
cpb[gpb]=true
dpb=dpb+1
end
end
end
return dpb
end
function W.pool(jpb,kpb)
local lpb=H.session()
local mpb,npb={},{}
