if H.Units[rpb.unit_id]and N.rows(rpb.unit_id)and not N.hidden(rpb.unit_id)and upb then
local vpb=N.isFarm(rpb.unit_id)
local wpb,xpb=pcall(vpb and function()
return N.farm(rpb,N.rows(rpb.unit_id).max)
end or N.score,rpb,jpb)
xpb=(wpb and xpb or 0)*(vpb and 1 or N.skinMul(rpb,kpb and kpb.skinSet))
local ypb=vpb and npb or mpb
if not ypb[rpb.unit_id]or xpb>ypb[rpb.unit_id].sc then
ypb[rpb.unit_id]={u=rpb,sc=xpb}
end
end
end
local zpb,Apb={},{}
