end
for Ypb=11,#zpb do
local Zpb=zpb[Ypb].u.unit_id
if N.allyBuff(Zpb)or N.BLESS.by[Zpb]or N.GALE[Zpb]then
table.insert(Jpb,zpb[Ypb].u)
end
end
if kpb and((kpb.flyChance or 0)>0 or kpb.mapFly or(kpb.shield or 0)>0)then
local _pb,aqb={},{}
for bqb=11,#zpb do
local cqb=zpb[bqb].u
