if N.airFrom(cqb.unit_id)==0 then
table.insert(_pb,cqb)
end
local eqb,fqb=tonumber(dqb and dqb.cd)or 0,tonumber((H.Units[cqb.unit_id]or{}).cost)or 0
if eqb>0 and fqb>0 and N.range(cqb,0)>=15 then
local gqb=N.attackInfo(dqb.atk,dqb.range)
table.insert(aqb,{u=cqb,v=gqb.n*gqb.hits/eqb/fqb*math.min(6,N.cap(cqb))})
end
end
table.sort(aqb,function(hqb,iqb)
return hqb.v>iqb.v
end)
for jqb=1,math.min(4,#_pb)do
table.insert(Jpb,_pb[jqb])
