for irb,jrb in ipairs(W.LADDER)do
local krb,lrb=0,0
for mrb,nrb in ipairs({0.92,1,1.08})do
local orb=W.run(brb,drb,{hpMul=jrb*nrb})
if orb.won then
krb=krb+1
end
lrb=lrb+orb.wave
end
erb,hrb=erb+krb,lrb/3
if jrb==1 then
frb,grb=krb,lrb/3
end
task.wait()
if krb==0 then
break
end
end
return erb,frb,grb,hrb
end
function W.bestTeam(prb,qrb,rrb,srb)
local trb=M.now()
srb=srb or 25
local urb=table.clone(qrb)
local vrb,wrb=W.cliff(prb,W.teamFrom(urb,prb.map))
local function xrb(yrb)
local zrb=0
for Arb,Brb in ipairs(yrb)do
if N.isFarm(Brb.unit_id)then
zrb=zrb+1
end
end
return zrb
end
local Crb=xrb(rrb)>0
local function Drb(Erb)
local Frb=0
for Grb,Hrb in ipairs(Erb)do
if not N.isFarm(Hrb.unit_id)and not N.allyBuff(Hrb.unit_id)then
Frb=Frb+N.cap(Hrb)
end
end
return Frb
end
local Irb
while#urb<6 do
local Jrb,Krb
local Lrb=Crb and xrb(urb)==0
for Mrb,Nrb in ipairs(rrb)do
local Orb=false
for Prb,Qrb in ipairs(urb)do
if Qrb.unit_id==Nrb.unit_id then
Orb=true
end
end
if not Orb and(not Lrb or N.isFarm(Nrb.unit_id))then
local Rrb=table.clone(urb)
table.insert(Rrb,Nrb)
local Srb=W.run(prb,W.teamFrom(Rrb,prb.map),{hpMul=vrb})
local Trb=W.objective(Srb)
if not Krb or Trb>Krb then
Jrb,Krb,Irb=Nrb,Trb,Srb
end
end
end
if not Jrb then
break
end
table.insert(urb,Jrb)
end
if Crb and xrb(urb)==0 then
local Urb,Vrb
for Wrb=1,#urb do
for Xrb,Yrb in ipairs(rrb)do
if N.isFarm(Yrb.unit_id)then
local Zrb=table.clone(urb)
Zrb[Wrb]=Yrb
local _rb=W.run(prb,W.teamFrom(Zrb,prb.map),{hpMul=vrb})
local asb=W.objective(_rb)
if not Vrb or asb>Vrb then
Urb,Vrb,Irb=Zrb,asb,_rb
end
end
end
end
if Urb then
urb=Urb
end
end
local function bsb(csb,dsb)
local esb=W.teamFrom(csb,prb.map)
return(W.objective(dsb)+W.objective(W.run(prb,esb,{hpMul=vrb*0.92}))+W.objective(W.run(prb,esb,{hpMul=vrb*1.08})))/3
end
local fsb,gsb=Irb or wrb,bsb(urb,Irb or wrb)
if type(rrb.rest)==pxc[1482]and#rrb.rest>0 then
local hsb,isb
for jsb,ksb in ipairs(urb)do
if not N.isFarm(ksb.unit_id)and not N.allyBuff(ksb.unit_id)then
local lsb,msb=pcall(N.score,ksb,prb.mod)
msb=(lsb and msb or 0)*N.skinMul(ksb,prb.skinSet)
if not isb or msb<isb then
hsb,isb=jsb,msb
end
end
end
if hsb then
local nsb,osb={},M.now()
for psb,qsb in ipairs(rrb.rest)do
if M.now()-osb>5 then
break
end
local rsb=false
for ssb,tsb in ipairs(urb)do
if tsb.unit_id==qsb.unit_id then
rsb=true
end
end
if not rsb then
local usb=table.clone(urb)
usb[hsb]=qsb
table.insert(nsb,{u=qsb,o=W.objective(W.run(prb,W.teamFrom(usb,prb.map),{hpMul=vrb}))})
end
end
table.sort(nsb,function(vsb,wsb)
return vsb.o>wsb.o
end)
rrb=table.clone(rrb)
for xsb=1,math.min(4,#nsb)do
table.insert(rrb,1,nsb[xsb].u)
end
trb=trb+(M.now()-osb)
end
end
for ysb=1,2 do
local zsb=false
for Asb=1,#urb do
for Bsb,Csb in ipairs(rrb)do
if M.now()-trb>srb then
return urb,fsb,vrb,wrb
end
local Dsb=false
for Esb,Fsb in ipairs(urb)do
if Fsb.unit_id==Csb.unit_id then
Dsb=true
end
end
if not Dsb then
local Gsb=table.clone(urb)
Gsb[Asb]=Csb
if(not Crb or xrb(Gsb)>0)and Drb(Gsb)>=math.min(8,Drb(urb))then
local Hsb=W.run(prb,W.teamFrom(Gsb,prb.map),{hpMul=vrb})
local Isb=W.objective(Hsb)
if Isb>gsb+1 then
Isb=bsb(Gsb,Hsb)
if Isb>gsb+1 then
urb,gsb,fsb,zsb=Gsb,Isb,Hsb,true
end
end
end
end
end
end
if not zsb then
break
end
end
return urb,fsb,vrb,wrb
end
function W.evolutions()
local Jsb=H.session()
