pcall(function()
Psb=Msb:get_number_of_owned_item(Osb)
end)
return Psb
end
for Qsb,Rsb in pairs(Jsb.profile_data.collection.owned_units)do
local Ssb=H.Units[Rsb.unit_id]
if Ssb and Ssb.evolve and Ssb.evolve.evolve_unit and not Ssb.evolve.hide_from_ui and not Lsb[Rsb.unit_id]and H.Units[Ssb.evolve.evolve_unit]then
Lsb[Rsb.unit_id]=true
local Tsb=Rsb.shiny and Ssb.evolve.shiny or Ssb.evolve.normal
if Tsb then
local Usb={}
for Vsb,Wsb in pairs(Tsb.item_requirement or{})do
