end
for Xsb,Ysb in pairs(Tsb.unit_requirement or{})do
local Zsb=0
for _sb,atb in pairs(Jsb.profile_data.collection.owned_units)do
if atb.unit_id==Ysb.unit_id and(not Ysb.shiny or atb.shiny)then
Zsb=Zsb+1
end
end
if Zsb<(Ysb.amount or 1)then
table.insert(Usb,string.format(pxc[2070],N.name(Ysb.unit_id),Zsb,Ysb.amount))
end
end
local btb=ab.killsShort(Jsb.collection:get_unit_by_uuid(Rsb.uuid)or Rsb,Tsb)
if btb then
