if#Usb<=1 then
local ctb=Jsb.collection:get_unit_by_uuid(Rsb.uuid)or Rsb
table.insert(Ksb,{u=ctb,from=Rsb.unit_id,to=Ssb.evolve.evolve_unit,missing=Usb,evolved={unit_id=Ssb.evolve.evolve_unit,uuid=pxc[2062]..tostring(ctb.uuid),xp=ctb.xp,traits=ctb.traits,trait_stats=ctb.trait_stats,further_modifiers=ctb.further_modifiers}})
end
end
end
end
return Ksb
end
function W.levelFor(dtb)
