return J.live.daily.ld,J.live.daily.challenge
end
if eb.is(dtb.level)and J.live.event and J.live.event.ld then
return J.live.event.ld,nil
end
local ftb=dtb.kind~=pxc[1496]or(etb and type(etb.ld)==pxc[1482]and etb.ld.id==dtb.level and etb.ch==dtb.challenge)
if etb and type(etb.ld)==pxc[1482]and ftb then
return etb.ld,etb.ch
end
if dtb.kind==pxc[1496]and H.Levels[dtb.level]then
local gtb=W.slim(H.Levels[dtb.level])
gtb._difficulty=pxc[1675]
gtb._gamemode=pxc[1496]
gtb._challenge=dtb.challenge
return gtb,dtb.challenge
