htb._gamemode=htb._OVERRIDE_GAMEMODE or((dtb.kind==pxc[1518]or dtb.kind==pxc[1635])and pxc[1518])or(htb.infinite and pxc[1501])or pxc[1517]
return htb,nil
end
end
function W.plan(itb,jtb,ktb,ltb)
local mtb,ntb=W.levelFor(itb)
if itb.ldOverride then
mtb=itb.ldOverride
