table.insert(Itb,Ktb.unit_id)
end
J.simTeam[itb.key]={uuids=xtb.winTeam,names=Htb,ids=Itb,won=true,wave=ptb.total,better=W.sig(ztb)~=utb.sig,cur={won=utb.won,wave=utb.wave},at=os.time(),label=itb.label,base=utb.sig,why=pxc[2722]}
j.log(1,pxc[2716],string.format(pxc[2723],itb.label,table.concat(Htb,pxc[1578]),Gtb and string.format((Ftb.ratio or 0)<0.1 and pxc[2724]or pxc[2725],Ftb.ratio or 0)or string.format(pxc[2726],Etb.wave),xtb.winTeamN or 1))
return utb
end
end
end
if I.simTeams and jtb then
local Ltb,Mtb,Ntb,Otb,Ptb=pcall(W.bestTeam,ptb,qtb,W.pool(otb,ptb),ktb)
if Ltb and Mtb then
local Qtb=W.sig(Mtb)~=utb.sig
if Qtb and utb.won and(utb.p or 0)>=0.92 then
local Rtb={}
for Stb,Ttb in ipairs(Mtb)do
table.insert(Rtb,N.name(Ttb.unit_id))
end
j.log(1,pxc[2716],string.format(pxc[2727],itb.label,table.concat(Rtb,pxc[1578])))
Mtb,Qtb=qtb,false
end
local Utb=pxc[411]
if Qtb then
local Vtb,Wtb=W.exam(ptb,qtb)
local Xtb,Ytb=W.exam(ptb,Mtb)
local Ztb= #Mtb> #qtb and Xtb==Vtb and Ytb>=Wtb
if Xtb>Vtb or(Xtb==Vtb and Ytb>Wtb)or Ztb then
