J.simTeam[itb.key]={uuids=dub,names=eub,ids=hub,won=cub.won,wave=cub.wave,better=Qtb,cur={won=utb.won,wave=utb.wave},at=os.time(),label=itb.label,base=utb.sig}
j.log(1,pxc[2716],string.format(pxc[2733],itb.label,cub.won and pxc[1841]or(pxc[2734]..cub.wave),table.concat(eub,pxc[1578]),Qtb and(string.format(pxc[2735],Otb,Ntb.won and pxc[1841]or pxc[1842],Ntb.wave,Ptb.won and pxc[1841]or pxc[1842],Ptb.wave)..Utb)or pxc[2736]))
local kub={}
