local rDb,sDb=kDb[qDb-1],kDb[qDb]
local tDb=(sDb-rDb).Magnitude
local uDb=math.max(1,math.floor(tDb/2))
for vDb=0,uDb-1 do
local wDb=rDb:Lerp(sDb,vDb/uDb)
table.insert(Q.samples,{pos=wDb,prog=(pDb+tDb*vDb/uDb)/math.max(1,nDb),lane=iDb.Name})
end
pDb=pDb+tDb
end
if kDb[#kDb]then
table.insert(Q.samples,{pos=kDb[#kDb],prog=1,lane=iDb.Name})
end
end
end
Q.laneCut,Q.laneWant,Q.laneFirst=nil,nil,nil
local xDb=tonumber(Q.ld and Q.ld._portal_lanes)
local yDb=W.laneList(Q.samples)
if xDb and xDb>=1 and yDb and#yDb>xDb then
Q.laneWant=xDb
end
Q.laneTotal=yDb and#yDb or 1
Q.countLanes()
end
function Q.countLanes()
local zDb,ADb,BDb={},0,0
for CDb,DDb in ipairs(Q.samples)do
local EDb=tostring(DDb.lane)
if not zDb[EDb]then
ADb=ADb+1
end
zDb[EDb]=(zDb[EDb]or 0)+1
BDb=BDb+1
end
Q.laneCount={n=ADb,by=zDb,avg=ADb>0 and BDb/ADb or 1}
end
function Q.portalLanes()
if not Q.laneWant or Q.laneCut then
return true
end
if Q.planning then
return false
end
local FDb,GDb={},0
for HDb,IDb in ipairs(workspace._UNITS:GetChildren())do
local JDb=IDb:FindFirstChild(pxc[1541])
if JDb and JDb:FindFirstChild(pxc[2909])and JDb.player.Value==nil and JDb:FindFirstChild(pxc[2910])and IDb:FindFirstChild(pxc[2911])then
local KDb=tostring(JDb.lane.Value)
if not FDb[KDb]then
FDb[KDb]=true
GDb=GDb+1
end
end
end
if GDb==0 then
if M.now()-(Q.startT or M.now())>45 then
Q.laneWant=nil
j.log(1,pxc[2912],pxc[2913])
return true
end
return false
end
Q.laneFirst=Q.laneFirst or M.now()
if GDb<Q.laneWant and M.now()-Q.laneFirst<10 then
return false
end
local LDb,MDb={},{}
for NDb,ODb in ipairs(Q.samples)do
if FDb[tostring(ODb.lane)]then
table.insert(LDb,ODb)
