j.log(1,pxc[2912],string.format(pxc[2915],Q.laneWant,Q.laneCut))
if Q.info and I.simSpots and not Q.joinedMid and not Q.random and not Q.infinite and not Q.trialId then
Q.planning=M.now()
task.spawn(function()
local SDb,TDb=pcall(Q.planSpots)
Q.planning=nil
if not SDb then
