end
function Q.buildWaves()
local UDb=Q.ld
local VDb=UDb and UDb._dungeon and type(UDb._override_waves)==pxc[1482]and UDb._override_waves or nil
local WDb=UDb and H.Waves[(VDb and VDb.template)or UDb.waves or UDb.id]
local XDb
