if not j.alive then
return
end
local dEb=H.prof()
local eEb=dEb and dEb.daily_infinite_reward_claims and dEb.daily_infinite_reward_claims[Q.ld.id]
local fEb=type(eEb)==pxc[1482]and(tonumber(eEb.highest_claimed_wave)or 0)>=cEb and os.time()-(tonumber(eEb.highest_claim_time)or 0)<900
if fEb then
