function Q.infStop(gEb)
local hEb=0
for iEb,jEb in ipairs(M.list(H.GS.DAILY_INFINITE_REWARDS))do
hEb=math.max(hEb,tonumber(jEb.wave)or 0)
end
if hEb<=0 or gEb<=hEb+1 then
return
end
local kEb=J.train.on
if Q.trainee and kEb and kEb.have+(kEb.got or 0)+(Q.trainTk or 0)<kEb.need then
return
end
if not P.every(pxc[2922],60)then
return
end
local lEb=O.rec(Q.key)
local mEb=tonumber(lEb.timed)or 0
local nEb=(mEb>0 and(lEb.sec or 0)>0)and math.max(0.5,((lEb.gems or 0)-200*mEb)/(lEb.sec/60))or 2.5
local oEb=pcall(O.pick)
local pEb
for qEb,rEb in ipairs(oEb and O.lastScored or{})do
if rEb.kind~=pxc[1501]and(not pEb or(rEb.score or 0)>(pEb.score or 0))then
pEb=rEb
end
end
if not pEb or(pEb.score or 0)<=nEb then
return
end
Q.stopping=true
j.log(1,pxc[2912],string.format(pxc[2923],gEb,nEb,pEb.score,pEb.label))
Q.sellAll()
end
function Q.trainLeave(sEb)
