end
local vEb,wEb,xEb=pcall(O.infDaily,H.prof(),Q.ld.id,(O.infReach(Q.key)))
if vEb and(wEb or 0)>0 and xEb>0 and sEb<=xEb then
j.status(pxc[2343],string.format(pxc[2924],N.name(tEb.id),tEb.what,xEb))
