if nGb.Magnitude<0.01 then
nGb=Vector3 .new(1,0,0)
end
nGb=nGb.Unit
local oGb=Vector3 .new(-nGb.Z,0,nGb.X)
for pGb,qGb in ipairs({3,4.5,6,8,10.5,13.5,17})do
for rGb,sGb in ipairs({1,-1})do
local tGb=lGb.pos+oGb*qGb*sGb
local uGb=string.format(pxc[2945],math.floor(tGb.X/1.5),math.floor(tGb.Z/1.5))
if not jGb[uGb]then
jGb[uGb]=true
