function Q.coverage(vGb,wGb)
local xGb={}
for yGb,zGb in ipairs(vGb)do
local AGb=zGb._stats
if not N.isFarm(AGb.id.Value)and AGb:FindFirstChild(pxc[1619])then
table.insert(xGb,{p=M.flat(zGb:GetPivot().Position),r=AGb.range.Value*(N.SUMMONER[AGb.id.Value]and N.SUMMONER[AGb.id.Value].reach or 1),air=Q.canAir(zGb)})
end
end
local BGb,CGb=0,0
if#xGb>0 then
for DGb,EGb in ipairs(Q.samples)do
if EGb.prog>CGb then
local FGb=M.flat(EGb.pos)
for GGb,HGb in ipairs(xGb)do
if(FGb-HGb.p).Magnitude<=HGb.r then
if EGb.prog>BGb then
BGb=EGb.prog
end
if HGb.air then
CGb=EGb.prog
break
end
end
end
end
end
end
local IGb,JGb={},Q.laneCount
if JGb and JGb.n>=2 and#xGb>0 then
local KGb={}
for LGb,MGb in ipairs(Q.samples)do
local NGb=M.flat(MGb.pos)
for OGb,PGb in ipairs(xGb)do
if(NGb-PGb.p).Magnitude<=PGb.r then
local QGb=tostring(MGb.lane)
KGb[QGb]=(KGb[QGb]or 0)+1
if MGb.prog>(IGb[QGb]or 0)then
IGb[QGb]=MGb.prog
end
break
end
end
end
local RGb,SGb={},0
for TGb,UGb in pairs(JGb.by)do
RGb[TGb]=(KGb[TGb]or 0)/math.max(1,UGb)
SGb=math.max(SGb,RGb[TGb])
end
Q.laneW={}
for VGb,WGb in pairs(JGb.by)do
Q.laneW[VGb]=(JGb.avg/math.max(1,WGb))*(1+1.5*(SGb>0 and(1-RGb[VGb]/SGb)or 0))
end
Q.laneFrac=RGb
else
Q.laneW,Q.laneFrac=nil,nil
end
local XGb,YGb,ZGb
if#xGb>0 then
for _Gb,aHb in ipairs(wGb)do
local bHb=(Q.laneW and aHb.lane and IGb[aHb.lane])or BGb
if aHb.hp>0 and aHb.prog>bHb+0.02 and aHb.prog>(XGb or 0)then
XGb,ZGb=aHb.prog,Q.laneW and aHb.lane or nil
end
if aHb.hp>0 and aHb.fly and aHb.prog>CGb+0.02 then
YGb=true
end
end
end
local cHb= #xGb>0 and(Q.pressure or 0)>=BGb-0.08
return{covEnd=BGb,airEnd=CGb,leak=XGb,leakLane=ZGb,covL=IGb,airLeak=YGb,push=cHb,units= #xGb}
end
function Q.needLastLine(dHb)
