if not RMb then
return nil
end
local SMb=N.range(BMb.u,0)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local TMb={}
for UMb,VMb in ipairs(Q.cands)do
local WMb,XMb,YMb=M.flat(VMb),0,0
for ZMb,_Mb in ipairs(Q.samples)do
if(M.flat(_Mb.pos)-WMb).Magnitude<=SMb then
YMb=YMb+1
if math.abs(_Mb.prog-RMb)<=0.05 then
XMb=XMb+1
local aNb=M.flat(_Mb.pos)
for bNb,cNb in ipairs(HMb)do
if(aNb-cNb.p).Magnitude<=cNb.r then
XMb=XMb-0.5
break
end
end
end
end
end
if XMb>0 then
table.insert(TMb,{pos=VMb,sc=XMb,cov=YMb})
end
if UMb%60==0 then
task.wait()
end
end
table.sort(TMb,function(dNb,eNb)
return dNb.sc>eNb.sc
end)
for fNb,gNb in ipairs(TMb)do
