function Q.lookAt(qQb)
local rQb,sQb=math.huge,nil
for tQb,uQb in ipairs(Q.samples)do
local vQb=(M.flat(uQb.pos)-M.flat(qQb)).Magnitude
if vQb<rQb then
rQb,sQb=vQb,uQb.pos
end
end
local wQb=sQb and M.flat(sQb-qQb)or Vector3 .new(0,0,-1)
return wQb.Magnitude>0.01 and wQb.Unit or Vector3 .new(0,0,-1)
end
function Q.place(xQb,yQb)
local zQb=N.isFarm(xQb.id)
local AQb,BQb=Q.bestSpot(xQb,zQb or(Q.random and N.idol(xQb.id)),(Q.trainee~=nil and xQb.uuid==Q.trainee)or N.ENTRY[xQb.id]==true or(Q.studyEntry==true and xQb.id==Q.trialId))
if not AQb then
Q.noSpot[xQb.uuid]=(Q.noSpot[xQb.uuid]or 0)+1
j.status(pxc[2985],pxc[2995]..N.name(xQb.id))
return false
end
local CQb=Q.money()
local DQb,EQb=j.request(pxc[2996],pxc[2997],xQb.uuid,H.Util.CFramePLV(AQb,Q.lookAt(AQb)))
if DQb and EQb then
Q.spent=Q.spent+(xQb.data.cost or 0)
table.insert(Q.actions,string.format(pxc[2998],N.name(xQb.id)))
j.log(1,pxc[2990],string.format(pxc[2999],N.name(xQb.id),Q.spotKey(AQb),BQb,yQb))
Q.placeLog=Q.placeLog or{}
table.insert(Q.placeLog,{t=math.floor(M.now()-(Q.startT or M.now())),w=Q.wave(),id=xQb.id,x=math.floor(AQb.X),z=math.floor(AQb.Z),cover=math.floor((BQb or 0)+0.5),why=tostring(yQb):sub(1,90)})
j.status(pxc[2985],string.format(pxc[3000],N.name(xQb.id),yQb))
Q.placedAt=Q.placedAt or{}
Q.placedAt[xQb.uuid]=(Q.placedAt[xQb.uuid]or 0)+1
return true
end
if CQb>=(xQb.data.cost or 0)and Q.random then
Q.placeFail=Q.placeFail or{}
Q.placeFail[xQb.uuid]=(Q.placeFail[xQb.uuid]or 0)+1
if Q.placeFail[xQb.uuid]>=2 then
Q.noSpot[xQb.uuid]=3
j.log(1,pxc[2990],string.format(pxc[3001],N.name(xQb.id),Q.fieldCount(),Q.FIELD_MAX))
end
end
if DQb and CQb>=(xQb.data.cost or 0)and not Q.random then
local FQb=Q.spotKey(AQb)
Q.refused[FQb]=true
local GQb=Q.mapKey()
J.blocked[GQb]=J.blocked[GQb]or{}
if not Q.refusedRun[FQb]then
J.blocked[GQb][FQb]=(tonumber(J.blocked[GQb][FQb])or 0)+1
Q.refusedRun[FQb]=true
end
Q.refusals=(Q.refusals or 0)+1
Q.unitRefusals[xQb.uuid]=(Q.unitRefusals[xQb.uuid]or 0)+1
if Q.unitRefusals[xQb.uuid]>=3 then
local HQb=math.max(1,Q.count(xQb.uuid))
if J.caps[xQb.uuid]~=HQb then
J.caps[xQb.uuid]=HQb
j.log(1,pxc[2990],string.format(pxc[3002],N.name(xQb.id),HQb))
end
end
j.log(2,pxc[2990],pxc[3003]..FQb..pxc[2028]..N.name(xQb.id))
j.saveSoon()
end
return false
end
function Q.count(IQb)
local JQb=0
for KQb,LQb in ipairs({workspace._UNITS,workspace:FindFirstChild(pxc[3004])})do
if LQb then
for MQb,NQb in ipairs(LQb:GetChildren())do
local OQb=NQb:FindFirstChild(pxc[1541])
if OQb and OQb:FindFirstChild(pxc[2993])and OQb.player.Value==G and OQb.uuid.Value==IQb then
JQb=JQb+1
end
end
end
end
