function Q.measure()
local PQb,QQb=Q.calRun,Q.info
if not(PQb and QQb)then
return
end
pcall(Q.sampleHelpers)
local RQb=M.now()
local SQb=Q.wave()
local TQb=Q.money()
if not PQb.start and TQb>0 and#Q.mine==0 then
PQb.start=TQb
end
if SQb~=PQb.lastW then
if Q.trialId and SQb>0 then
Q.trialTrace=Q.trialTrace or{}
local UQb,VQb,WQb,XQb=0,{},0,0
for YQb,ZQb in ipairs(Q.mine)do
local _Qb=ZQb._stats
if _Qb.id.Value==Q.trialId then
UQb=UQb+1
table.insert(VQb,tostring(_Qb.upgrade.Value))
elseif not N.isFarm(_Qb.id.Value)then
XQb=XQb+1
end
end
pcall(Q.sampleHelpers,true)
for aRb,bRb in pairs(Q.ownDealt)do
if bRb.id==Q.trialId then
WQb=WQb+bRb.v
end
end
local cRb=0
for dRb,eRb in pairs(Q.helperDealt)do
if eRb.owner==Q.trialId then
cRb=cRb+eRb.v
end
end
table.insert(Q.trialTrace,string.format(pxc[3005],SQb,RQb-(Q.startT or RQb),TQb,table.concat(VQb,pxc[2095]),XQb,WQb+cRb,#(Q.enemies or{}),Q.hpAliveRaw or 0,Q.waveMax[SQb-1]or 0,Q.teamDps or 0))
end
if PQb.lastW and PQb.lastW>0 and PQb.lastWT then
table.insert(PQb.waveSec,RQb-PQb.lastWT)
end
if PQb.paidT and SQb>0 and RQb-PQb.paidT<15 then
table.insert(PQb.skip,RQb-PQb.paidT)
end
PQb.paidT=nil
if SQb>0 then
PQb.alive[tostring(SQb)]=Q.hpAliveRaw or 0
end
PQb.lastW,PQb.lastWT=SQb,RQb
end
local fRb=workspace:FindFirstChild(pxc[3006])
if fRb and SQb>0 then
PQb.timer[tostring(SQb)]=math.max(PQb.timer[tostring(SQb)]or 0,tonumber(fRb.Value)or 0)
end
local gRb=TQb-(Q.lastMoneyR or TQb)
Q.lastMoneyR=TQb
Q.incomeLog=Q.incomeLog or{}
if gRb>0 then
table.insert(Q.incomeLog,{t=RQb,y=gRb})
end
while Q.incomeLog[1]and RQb-Q.incomeLog[1].t>30 do
table.remove(Q.incomeLog,1)
end
local hRb=0
for iRb,jRb in ipairs(Q.incomeLog)do
hRb=hRb+jRb.y
end
local kRb=math.min(30,RQb-(Q.startT or RQb))
Q.incomeRate=kRb>=8 and hRb/kRb or nil
for lRb,mRb in ipairs(Q.enemies)do
local nRb=mRb.m
local oRb=Q.track[nRb]
if not oRb then
local pRb=nRb._stats
local qRb=nRb:FindFirstChildOfClass(pxc[2933])
local rRb=QQb.cfgById[pRb.id.Value]
local sRb=rRb and W.baseStats(QQb,rRb)
if qRb and sRb and SQb>0 then
local tRb=sRb*QQb.hpRaw*W.waveScale(QQb,SQb,QQb.list[SQb])
if tRb>0 and qRb.MaxHealth>0 then
table.insert(PQb.hp,qRb.MaxHealth/tRb)
end
end
Q.track[nRb]={t=RQb,p=mRb.prog,sp=(pRb:FindFirstChild(pxc[3007])and tonumber(pRb.speed.Value))or 1}
if SQb>0 then
PQb.spawn[tostring(SQb)]=(PQb.spawn[tostring(SQb)]or 0)+1
PQb.spawnLast[tostring(SQb)]=RQb-(PQb.lastWT or RQb)
end
elseif not oRb.done and RQb-oRb.t>=15 then
