function Q.holdGain(LUb,MUb)
if Q.random or not MUb or not Q.info then
return 0
end
local NUb=N.attackInfo(MUb.atk,MUb.range)
if(NUb.stun or 0)<=0 and(NUb.slowTime or 0)<=0 then
return 0
end
local OUb=0
for PUb,QUb in ipairs(Q.mine or{})do
local RUb=QUb._stats
local SUb=N.rows(RUb.id.Value)
local TUb=SUb and SUb[math.min(RUb.upgrade.Value,SUb.max)]
local UUb=TUb and TUb.atk and N.attackInfo(TUb.atk,TUb.range)
if UUb and((UUb.stun or 0)>0 or(UUb.slowTime or 0)>0)then
OUb=OUb+1
end
end
local VUb,WUb=W.mask(Q.info.map,N.range(LUb.u,0)*(Q.info.rangeScale or 1)),0
for XUb=1,W.BINS do
if VUb[XUb]then
WUb=WUb+1
end
end
local YUb=Q.depth and Q.depth.units>0 and Q.depth.covEnd or 1
local ZUb=(N.airFrom(LUb.id)==0)and 1 or(1-(1-H.FLY_GROUND)*math.min(1,Q.info.flyChance or 0))
return V.holdGain(NUb,Q.teamDps or 0,WUb/(math.max(0.1,YUb)*W.BINS)*ZUb,OUb)
