function Q.buffGain(_Ub)
local aVb=N.allyBuff(_Ub.id)
if not aVb then
return 0
end
local bVb=Q.buffShort(aVb)
local cVb=J.stack[aVb.attack]
local dVb=cVb and cVb.stacks and(cVb.cap or 1)or nil
local eVb,fVb=pcall(N.range,_Ub.u,0)
fVb=(eVb and tonumber(fVb)or 15)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local gVb=dVb and I.community and tonumber(aVb.time)and tonumber(aVb.cd)
local function hVb(iVb,jVb)
local kVb=math.floor(iVb*aVb.time/math.max(1,aVb.cd)+0.001)
return math.min(dVb,(1+jVb)^kVb-1)
end
local lVb=0
for mVb,nVb in ipairs(bVb)do
local oVb=0
for pVb,qVb in ipairs(bVb)do
if(qVb.pos-nVb.pos).Magnitude<=fVb then
local rVb=aVb.types[qVb.base]
local sVb=rVb*aVb.uptime
if gVb then
local tVb,uVb=hVb(qVb.n,rVb),qVb.n+1
while uVb<qVb.n+6 and hVb(uVb,rVb)<=tVb+0.001 do
uVb=uVb+1
end
sVb=math.max(0,(hVb(uVb,rVb)-tVb)/(uVb-qVb.n))
elseif dVb then
sVb=math.max(0,math.min(dVb,(qVb.n+1)*rVb*aVb.uptime)-math.min(dVb,qVb.n*rVb*aVb.uptime))
end
oVb=oVb+qVb.dps*sVb
end
end
lVb=math.max(lVb,oVb)
end
return lVb*(gVb and 1 or 0.7)
end
function Q.buffWanted(vVb)
return Q.buffGain(vVb)>0.01*(Q.teamDps or 0)
