function Q.blessGain(CVb)
if not N.BLESS.by[CVb.id]then
return 0
end
local DVb,EVb=0,0
for FVb,GVb in ipairs(Q.mine or{})do
local HVb=GVb._stats.id.Value
if N.BLESS.by[HVb]then
DVb=DVb+1
end
if N.SUMMONER[HVb]then
EVb=EVb+Q.liveDps(GVb,HVb)
end
end
if DVb>=N.BLESS.cap then
